from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: dict[int, dict] = {}

    def book(
        self, patient: str, doctor: str, start: datetime, end: datetime, now: datetime
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Appointment start time must be before end time.")

        # Requirement 1: Booking an appointment that starts before `now` raises ValueError.
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        # Requirement 2: A patient can have at most one upcoming appointment.
        for appt in self._appointments.values():
            if not appt["cancelled"] and appt["patient"] == patient:
                if appt["end"] > now:
                    raise ValueError(
                        f"Patient '{patient}' already has an upcoming appointment."
                    )

        # Requirement 3 & 4: Check if the doctor's time slot is available.
        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor '{doctor}' is not available during the requested time slot."
            )

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "id": appt_id,
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            "slot_blocked": True,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment with id {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt["cancelled"]:
            return

        appt["cancelled"] = True

        # Requirement 4: Cancelling less than 24 hours before its start keeps the slot blocked.
        # Otherwise, the time slot is freed.
        if appt["start"] - now >= timedelta(hours=24):
            appt["slot_blocked"] = False
        else:
            appt["slot_blocked"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start time must be before end time.")

        for appt in self._appointments.values():
            if appt["doctor"] == doctor and appt["slot_blocked"]:
                # Check for overlap: max(start1, start2) < min(end1, end2)
                if max(start, appt["start"]) < min(end, appt["end"]):
                    return False

        return True
```

